def backfill_from_the_ledger(apps, schema_editor):
    """Mark verified every part that already holds credit.

    Credit now stands on a Lead's verification, so a part credited under the
    old rule (by its task closing) is stamped as verified by whoever the
    record names, at the time it was written. Without this, the first
    verification sweep would read every existing credit as unverified.

    A verifier with no membership on the project resolves to null, which the
    page reports as a former member. Hand-entered records are skipped: they
    stand on no submission.
    """
    ContributionRecord = apps.get_model("contributions", "ContributionRecord")
    ProjectMember = apps.get_model("projects", "ProjectMember")
    TaskLog = apps.get_model("tasks", "TaskLog")

    records = ContributionRecord.objects.filter(
        added_by_hand=False,
        task_log__isnull=False,
        task_log__verified_at__isnull=True,
    ).order_by("closed_at")
    member_cache = {}
    for record in records.iterator():
        key = (record.project_id, record.verified_by_id)
        if key not in member_cache:
            member_cache[key] = (
                ProjectMember.objects.filter(
                    project_id=record.project_id, users=record.verified_by_id
                )
                .values_list("pk", flat=True)
                .first()
                if record.verified_by_id
                else None
            )
        TaskLog.objects.filter(
            pk=record.task_log_id, verified_at__isnull=True
        ).update(
            verified_at=record.closed_at,
            verified_by_id=member_cache[key],
        )


